// Generated from HYG Database v4: https://github.com/astronexus/HYG-Database
// Licensed CC BY-SA 4.0. Six quantized bytes per star preserve display-level precision.
const encoded = ''
let cache: Float32Array | undefined

export const starCount = 112787

export function loadStarField() {
  if (cache) return cache
  const bytes = Uint8Array.from(atob(encoded), (character) => character.charCodeAt(0))
  const view = new DataView(bytes.buffer)
  const field = new Float32Array(starCount * 4)
  for (let index = 0; index < starCount; index += 1) {
    const source = index * 6
    const target = index * 4
    field[target] = view.getUint16(source, true) / 65535 * 24
    field[target + 1] = view.getInt16(source + 2, true) / 32767 * 90
    field[target + 2] = view.getUint8(source + 4) / 255 * 12.5 - 2
    field[target + 3] = view.getUint8(source + 5) / 255 * 3 - .5
  }
  cache = field
  return field
}
